CREATE OR REPLACE FUNCTION public._venta_exigir_cobro_vtd()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.estado = 'COMPLETADA' and old.estado is distinct from new.estado
     and new.numero like 'VTD-%'
     and new.cobro_exigible
     and not new.pago_posterior
     and coalesce(new.total, 0) > 0
     and not exists (select 1 from venta_pago where venta_id = new.id) then
    raise exception '% no está cobrada. Cóbrala en caja antes de entregar, o márcala como pago posterior con motivo.', new.numero
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.app_usuario(p_fallback text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select nombre from public.perfil where id = auth.uid()),
    p_fallback,
    'sistema'
  );
$function$
CREATE OR REPLACE FUNCTION public.crear_solicitud_traslado(p_motivo motivo_traslado, p_lineas jsonb, p_usuario text DEFAULT NULL::text, p_sucursal_origen_id bigint DEFAULT 1, p_sucursal_destino_id bigint DEFAULT 2, p_referencia text DEFAULT NULL::text, p_nota text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_id bigint; v_linea jsonb; v_prod bigint; v_pres bigint;
  v_factor numeric; v_cant_pres numeric; v_cant numeric;
begin
  if jsonb_typeof(p_lineas) <> 'array' or jsonb_array_length(p_lineas) = 0 then
    raise exception 'p_lineas debe ser un array no vacío';
  end if;

  insert into solicitud_traslado (motivo, sucursal_origen_id, sucursal_destino_id,
                                  referencia, nota, solicitado_por)
  values (p_motivo, p_sucursal_origen_id, p_sucursal_destino_id,
          p_referencia, p_nota, p_usuario)
  returning id into v_id;

  for v_linea in select * from jsonb_array_elements(p_lineas) loop
    v_prod := (v_linea->>'producto_id')::bigint;
    if v_prod is null then raise exception 'Cada línea requiere producto_id'; end if;
    v_pres := (v_linea->>'presentacion_id')::bigint;

    if v_pres is not null then
      select factor_unidad_base into v_factor
        from presentacion where id = v_pres and producto_id = v_prod;
      if v_factor is null then
        raise exception 'La presentación % no pertenece al producto %', v_pres, v_prod;
      end if;
      v_cant_pres := (v_linea->>'cantidad_presentacion')::numeric;
      if v_cant_pres is null or v_cant_pres <= 0 then
        raise exception 'cantidad_presentacion debe ser positiva';
      end if;
      v_cant := v_cant_pres * v_factor;
    else
      v_cant := (v_linea->>'cantidad_base')::numeric;
      v_cant_pres := v_cant;
      if v_cant is null or v_cant <= 0 then raise exception 'cantidad_base debe ser positiva'; end if;
    end if;

    insert into solicitud_traslado_linea (solicitud_id, producto_id, presentacion_id,
                                          cantidad_presentacion, cantidad_base, nota)
    values (v_id, v_prod, v_pres, v_cant_pres, v_cant, v_linea->>'nota');
  end loop;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.recibir_traslado(p_solicitud_id bigint, p_usuario text DEFAULT NULL::text, p_lineas jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_sol           solicitud_traslado%rowtype;
  v_ubic_destino  bigint;
  v_l             record;
  v_despachada    numeric;
  v_recibida      numeric;
  v_falta         numeric;
  v_stock_actual  numeric;
  v_faltantes     int   := 0;
  v_detalle       jsonb := '[]'::jsonb;
  v_no_despachadas jsonb;
begin
  select * into v_sol from solicitud_traslado where id = p_solicitud_id for update;
  if not found then
    raise exception 'Solicitud % no existe', p_solicitud_id;
  end if;
  if v_sol.estado <> 'EN_TRANSITO' then
    raise exception 'La solicitud % está en estado % y no se puede recibir', p_solicitud_id, v_sol.estado;
  end if;

  v_ubic_destino := coalesce(v_sol.ubicacion_destino_id, ubicacion_recepcion(v_sol.sucursal_destino_id));
  if v_ubic_destino is null then
    raise exception 'La sucursal destino % no tiene ubicación de recepción configurada', v_sol.sucursal_destino_id;
  end if;

  -- F3: aviso de líneas que nunca salieron (casos heredados antes de este fix)
  select coalesce(jsonb_agg(jsonb_build_object('linea_id', id, 'producto_id', producto_id, 'cantidad_base', cantidad_base) order by id), '[]'::jsonb)
    into v_no_despachadas
    from solicitud_traslado_linea
   where solicitud_id = p_solicitud_id and estado = 'POR_DESPACHAR';

  -- F3: solo se reciben líneas realmente despachadas
  for v_l in select * from solicitud_traslado_linea
              where solicitud_id = p_solicitud_id and estado = 'DESPACHADA' order by id
  loop
    v_despachada := coalesce(v_l.cantidad_despachada, 0);

    v_recibida := v_despachada;
    if p_lineas is not null then
      select (x->>'cantidad_base')::numeric into v_recibida
        from jsonb_array_elements(p_lineas) x
       where (x->>'linea_id')::bigint = v_l.id;
      v_recibida := coalesce(v_recibida, v_despachada);
    end if;

    if v_recibida < 0 or v_recibida > v_despachada then
      raise exception 'Cantidad recibida inválida en la línea % (recibido %, despachado %)', v_l.id, v_recibida, v_despachada;
    end if;

    v_falta := v_despachada - v_recibida;

    if v_falta > 0 then
      perform pg_advisory_xact_lock(hashtext('stock:' || v_l.producto_id || ':' || v_ubic_destino));

      select coalesce(sum(sa.cantidad_base), 0) into v_stock_actual
        from stock_actual sa
       where sa.producto_id = v_l.producto_id and sa.ubicacion_id = v_ubic_destino;

      perform registrar_ajuste(v_l.producto_id, v_ubic_destino, v_stock_actual - v_falta,
                               'Faltante en traslado', 'Traslado #' || p_solicitud_id, p_usuario, current_date);

      v_faltantes := v_faltantes + 1;
      v_detalle := v_detalle || jsonb_build_object(
        'linea_id', v_l.id, 'producto_id', v_l.producto_id, 'despachado', v_despachada,
        'recibido', v_recibida, 'faltante', v_falta, 'ubicacion_id', v_ubic_destino);
    end if;

    update solicitud_traslado_linea set cantidad_recibida = v_recibida where id = v_l.id;
  end loop;

  update solicitud_traslado
     set estado = 'RECIBIDO', recibido_por = p_usuario, recibido_en = now()
   where id = p_solicitud_id;

  return jsonb_build_object(
    'solicitud_id',          p_solicitud_id,
    'estado',                'RECIBIDO',
    'ubicacion_destino_id',  v_ubic_destino,
    'lineas_con_faltante',   v_faltantes,
    'faltantes',             v_detalle,
    'lineas_no_despachadas', v_no_despachadas);
end;
$function$
CREATE OR REPLACE FUNCTION public.registrar_ajuste(p_producto_id bigint, p_ubicacion_id bigint, p_cantidad_base_objetivo numeric, p_motivo text, p_referencia text DEFAULT NULL::text, p_usuario character varying DEFAULT NULL::character varying, p_fecha date DEFAULT CURRENT_DATE)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_stock numeric; v_delta numeric; v_id bigint;
begin
  if p_cantidad_base_objetivo < 0 then
    raise exception 'El objetivo de ajuste no puede ser negativo (%).', p_cantidad_base_objetivo;
  end if;
  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'Un ajuste exige motivo (queda en auditoría).';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_producto_id::text || ':' || p_ubicacion_id::text, 0));

  select cantidad_base into v_stock from stock_actual
  where producto_id = p_producto_id and ubicacion_id = p_ubicacion_id;
  v_stock := coalesce(v_stock, 0);

  v_delta := p_cantidad_base_objetivo - v_stock;
  if v_delta = 0 then
    return null;
  end if;

  insert into kardex_transacciones (
    producto_id, ubicacion_id, cantidad, tipo_movimiento, referencia,
    motivo, fecha_efectiva, creado_por
  ) values (
    p_producto_id, p_ubicacion_id, v_delta, 'AJUSTE', coalesce(p_referencia, p_motivo),
    p_motivo, p_fecha, public.app_usuario(p_usuario)
  )
  returning id into v_id;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.registrar_entrada(p_presentacion_id bigint, p_ubicacion_id bigint, p_cantidad_pres numeric, p_referencia text, p_usuario character varying DEFAULT NULL::character varying, p_fecha date DEFAULT CURRENT_DATE, p_costo_unitario numeric DEFAULT NULL::numeric, p_idempotencia text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_producto_id bigint; v_factor numeric; v_base numeric; v_id bigint;
begin
  if p_cantidad_pres <= 0 then
    raise exception 'La cantidad de entrada debe ser > 0 (recibido: %).', p_cantidad_pres;
  end if;

  select producto_id, factor_unidad_base into v_producto_id, v_factor
  from presentacion where id = p_presentacion_id;
  if not found then
    raise exception 'Presentación % inexistente.', p_presentacion_id;
  end if;

  if p_idempotencia is not null then
    select id into v_id from kardex_transacciones where idempotencia_clave = p_idempotencia;
    if found then return v_id; end if;
  end if;

  v_base := p_cantidad_pres * v_factor;

  insert into kardex_transacciones (
    producto_id, ubicacion_id, cantidad, tipo_movimiento, referencia,
    presentacion_id, cantidad_origen, factor_a_base_snap,
    costo_unitario_base, fecha_efectiva, creado_por, idempotencia_clave
  ) values (
    v_producto_id, p_ubicacion_id, v_base, 'ENTRADA', coalesce(p_referencia, 'ENTRADA'),
    p_presentacion_id, p_cantidad_pres, v_factor,
    p_costo_unitario, p_fecha, public.app_usuario(p_usuario), p_idempotencia
  )
  on conflict (idempotencia_clave) do nothing
  returning id into v_id;

  if v_id is null and p_idempotencia is not null then
    select id into v_id from kardex_transacciones where idempotencia_clave = p_idempotencia;
  end if;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.registrar_salida(p_presentacion_id bigint, p_ubicacion_id bigint, p_cantidad_pres numeric, p_referencia text, p_usuario character varying DEFAULT NULL::character varying, p_fecha date DEFAULT CURRENT_DATE, p_idempotencia text DEFAULT NULL::text, p_permitir_sobregiro boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_producto_id bigint; v_factor numeric; v_base numeric; v_stock numeric; v_id bigint;
begin
  if p_cantidad_pres <= 0 then
    raise exception 'La cantidad de salida debe ser > 0 (recibido: %).', p_cantidad_pres;
  end if;

  select producto_id, factor_unidad_base into v_producto_id, v_factor
  from presentacion where id = p_presentacion_id;
  if not found then
    raise exception 'Presentación % inexistente.', p_presentacion_id;
  end if;

  if p_idempotencia is not null then
    select id into v_id from kardex_transacciones where idempotencia_clave = p_idempotencia;
    if found then return v_id; end if;
  end if;

  v_base := p_cantidad_pres * v_factor;

  perform pg_advisory_xact_lock(
    hashtextextended(v_producto_id::text || ':' || p_ubicacion_id::text, 0));

  select cantidad_base into v_stock from stock_actual
  where producto_id = v_producto_id and ubicacion_id = p_ubicacion_id;
  v_stock := coalesce(v_stock, 0);

  if v_stock < v_base and not p_permitir_sobregiro then
    raise exception
      'Stock insuficiente en ubicación %: hay % en base, se piden %.',
      p_ubicacion_id, v_stock, v_base;
  end if;

  insert into kardex_transacciones (
    producto_id, ubicacion_id, cantidad, tipo_movimiento, referencia,
    presentacion_id, cantidad_origen, factor_a_base_snap,
    fecha_efectiva, creado_por, idempotencia_clave
  ) values (
    v_producto_id, p_ubicacion_id, -v_base, 'SALIDA', coalesce(p_referencia, 'SALIDA'),
    p_presentacion_id, p_cantidad_pres, v_factor,
    p_fecha, public.app_usuario(p_usuario), p_idempotencia
  )
  on conflict (idempotencia_clave) do nothing
  returning id into v_id;

  if v_id is null and p_idempotencia is not null then
    select id into v_id from kardex_transacciones where idempotencia_clave = p_idempotencia;
  end if;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.registrar_traslado(p_presentacion_id bigint, p_ubicacion_origen bigint, p_ubicacion_destino bigint, p_cantidad_pres numeric, p_referencia text DEFAULT NULL::text, p_usuario character varying DEFAULT NULL::character varying, p_fecha date DEFAULT CURRENT_DATE)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_producto_id bigint; v_factor numeric; v_base numeric; v_stock numeric;
  v_grupo bigint; v_actor text;
begin
  if p_ubicacion_origen = p_ubicacion_destino then
    raise exception 'Origen y destino no pueden ser la misma ubicación.';
  end if;
  if p_cantidad_pres <= 0 then
    raise exception 'La cantidad a trasladar debe ser > 0 (recibido: %).', p_cantidad_pres;
  end if;

  select producto_id, factor_unidad_base into v_producto_id, v_factor
  from presentacion where id = p_presentacion_id;
  if not found then
    raise exception 'Presentación % inexistente.', p_presentacion_id;
  end if;

  v_base := p_cantidad_pres * v_factor;

  perform pg_advisory_xact_lock(
    hashtextextended(v_producto_id::text || ':' ||
      least(p_ubicacion_origen, p_ubicacion_destino)::text, 0));
  perform pg_advisory_xact_lock(
    hashtextextended(v_producto_id::text || ':' ||
      greatest(p_ubicacion_origen, p_ubicacion_destino)::text, 0));

  select cantidad_base into v_stock from stock_actual
  where producto_id = v_producto_id and ubicacion_id = p_ubicacion_origen;
  v_stock := coalesce(v_stock, 0);

  if v_stock < v_base then
    raise exception
      'Stock insuficiente en origen %: hay % en base, se trasladan %.',
      p_ubicacion_origen, v_stock, v_base;
  end if;

  v_grupo := nextval('traslado_grupo_seq');
  v_actor := public.app_usuario(p_usuario);

  insert into kardex_transacciones (
    producto_id, ubicacion_id, cantidad, tipo_movimiento, referencia,
    presentacion_id, cantidad_origen, factor_a_base_snap,
    traslado_grupo_id, fecha_efectiva, creado_por
  ) values
    (v_producto_id, p_ubicacion_origen, -v_base, 'TRASLADO',
      coalesce(p_referencia, 'TRASLADO'),
      p_presentacion_id, p_cantidad_pres, v_factor, v_grupo, p_fecha, v_actor),
    (v_producto_id, p_ubicacion_destino, v_base, 'TRASLADO',
      coalesce(p_referencia, 'TRASLADO'),
      p_presentacion_id, p_cantidad_pres, v_factor, v_grupo, p_fecha, v_actor);

  return v_grupo;
end;
$function$
CREATE OR REPLACE FUNCTION public.resolver_ubicacion_salida(p_producto_id bigint, p_ubicacion_venta bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_sucursal bigint;
  v_virtual  boolean;
  v_dest     bigint;
begin
  select u.sucursal_id, u.excluye_disponible
    into v_sucursal, v_virtual
    from ubicacion u
   where u.id = p_ubicacion_venta;

  if not found then
    raise exception 'Ubicación % inexistente', p_ubicacion_venta;
  end if;

  -- Ubicación física real: la venta ya apunta al estante correcto.
  if not v_virtual then
    return p_ubicacion_venta;
  end if;

  -- Nivel 1 — estante con mayor stock disponible en la misma sucursal.
  select sa.ubicacion_id
    into v_dest
    from stock_actual sa
    join ubicacion u on u.id = sa.ubicacion_id
   where sa.producto_id = p_producto_id
     and u.sucursal_id = v_sucursal
     and u.excluye_disponible = false
     and sa.cantidad_base > 0
   order by sa.cantidad_base desc, sa.ubicacion_id
   limit 1;

  if v_dest is not null then
    return v_dest;
  end if;

  -- Nivel 2 — sin stock en ningún estante: el de movimiento más reciente.
  select k.ubicacion_id
    into v_dest
    from kardex_transacciones k
    join ubicacion u on u.id = k.ubicacion_id
   where k.producto_id = p_producto_id
     and u.sucursal_id = v_sucursal
     and u.excluye_disponible = false
   order by k.creado_en desc, k.id desc
   limit 1;

  if v_dest is not null then
    return v_dest;
  end if;

  -- Nivel 3 — nunca visto en la sucursal: conservar la virtual.
  return p_ubicacion_venta;
end;
$function$
CREATE OR REPLACE FUNCTION public.ubicacion_recepcion(p_sucursal_id bigint)
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select id from ubicacion
   where sucursal_id = p_sucursal_id
   order by es_recepcion desc, id
   limit 1;
$function$
CREATE OR REPLACE FUNCTION public.trg_kardex_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'kardex_transacciones es append-only: % no permitido', TG_OP;
END;
$function$
CREATE OR REPLACE FUNCTION public.trg_stock_desde_kardex()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO stock_actual (producto_id, ubicacion_id, cantidad_base, actualizado_en)
    VALUES (NEW.producto_id, NEW.ubicacion_id, NEW.cantidad, now())
    ON CONFLICT (producto_id, ubicacion_id) DO UPDATE
        SET cantidad_base  = stock_actual.cantidad_base + EXCLUDED.cantidad_base,
            actualizado_en = now();
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.completar_venta(p_venta_id bigint, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_venta           venta%rowtype;
  v_linea           venta_linea%rowtype;
  v_presentacion_id bigint;
  v_factor          numeric;
  v_cant_pres       numeric;
  v_kardex_id       bigint;
  v_ubicacion_id    bigint;
  v_subtotal        numeric := 0;
  v_count           int := 0;
begin
  select * into v_venta from venta where id = p_venta_id for update;
  if not found then
    raise exception 'Venta % no existe', p_venta_id;
  end if;
  if v_venta.estado <> 'ABIERTA' then
    raise exception 'Venta % está en estado % y no admite checkout', p_venta_id, v_venta.estado;
  end if;

  for v_linea in select * from venta_linea where venta_id = p_venta_id order by id loop
    v_count := v_count + 1;

    v_presentacion_id := v_linea.presentacion_id;

    if v_presentacion_id is null then
      select id, factor_unidad_base into v_presentacion_id, v_factor
        from presentacion
       where producto_id = v_linea.producto_id and es_base = true
       limit 1;
      if v_presentacion_id is null then
        raise exception 'Producto % no tiene presentación base', v_linea.producto_id;
      end if;
      v_cant_pres := v_linea.cantidad;
    else
      select factor_unidad_base into v_factor
        from presentacion where id = v_presentacion_id;
      if v_factor is null then
        raise exception 'Presentación % inexistente (línea %)', v_presentacion_id, v_linea.id;
      end if;
      v_cant_pres := coalesce(v_linea.cantidad_presentacion, v_linea.cantidad);
    end if;

    if round(v_cant_pres * v_factor, 4) <> round(v_linea.cantidad, 4) then
      raise exception
        'Línea % incoherente: % x factor % da % pero cantidad base es %. Abortado antes de escribir Kardex.',
        v_linea.id, v_cant_pres, v_factor, v_cant_pres * v_factor, v_linea.cantidad;
    end if;

    -- FIX 2026-09-09: resolver el estante físico real. Antes descontaba
    -- siempre contra v_venta.ubicacion_id, que en VTD es la 31 (virtual) —
    -- la mercadería salía del estante pero el Kardex debitaba un balde que
    -- además todos los totales filtran. Ver encabezado de esta migración.
    v_ubicacion_id := resolver_ubicacion_salida(v_linea.producto_id, v_venta.ubicacion_id);

    -- TEMPORAL (2026-08-26, revisado 2026-09-09): sobregiro incondicional.
    -- Se cierra en el PASO 4 del plan de regularización, reemplazando por
    -- permite_sobregiro_sucursal(v_linea.producto_id, 1), una vez que los 30
    -- productos sin stock suficiente tengan entrada real.
    --
    -- FIX 2026-08-29: p_fecha usa v_linea.creado_en (momento real del punto
    -- de venta, en hora local Bolivia) en vez del CURRENT_DATE por defecto.
    select registrar_salida(
      p_presentacion_id => v_presentacion_id,
      p_ubicacion_id    => v_ubicacion_id,
      p_cantidad_pres   => v_cant_pres,
      p_referencia      => 'Venta #' || p_venta_id,
      p_usuario         => p_usuario,
      p_fecha           => (v_linea.creado_en at time zone 'America/La_Paz')::date,
      p_idempotencia    => 'venta_linea:' || v_linea.id,
      p_permitir_sobregiro => true
    ) into v_kardex_id;

    update venta_linea
       set presentacion_id = v_presentacion_id,
           kardex_transaccion_id = v_kardex_id
     where id = v_linea.id;

    v_subtotal := v_subtotal + round(v_linea.precio_unitario * v_cant_pres, 2);
  end loop;

  if v_count = 0 then
    raise exception 'La venta % no tiene líneas', p_venta_id;
  end if;

  update venta
     set subtotal      = v_subtotal,
         total         = round(v_subtotal - coalesce(descuento_total, 0), 2),
         estado        = 'COMPLETADA',
         completado_en = now(),
         creado_por    = coalesce(creado_por, p_usuario)
   where id = p_venta_id;

  return jsonb_build_object(
    'venta_id', p_venta_id,
    'lineas',   v_count,
    'subtotal', v_subtotal,
    'total',    round(v_subtotal - coalesce(v_venta.descuento_total, 0), 2)
  );
end;
